<?php
/**
 * Solar Line Duotone icons.
 *
 * The JSON map is generated by `bun run icons` (scripts/build-icons.mjs).
 *
 * @package Sekeco
 */

defined( 'ABSPATH' ) || exit;

/**
 * Icon bodies keyed by name.
 *
 * @return array<string,string>
 */
function sekeco_icons() {
	static $icons = null;

	if ( null === $icons ) {
		$file  = SEKECO_PATH . 'assets/icons/solar-line-duotone.json';
		$data  = file_exists( $file ) ? json_decode( (string) file_get_contents( $file ), true ) : array();
		$icons = is_array( $data ) ? $data : array();
	}

	return $icons;
}

/**
 * Whether an icon exists.
 *
 * @param string $name Icon name.
 * @return bool
 */
function sekeco_icon_exists( $name ) {
	$icons = sekeco_icons();

	return isset( $icons[ $name ] );
}

/**
 * Inline SVG for a Solar icon. Decorative unless a label is given.
 *
 * @param string $name Icon name.
 * @param array  $args Optional: class, size, label.
 * @return string
 */
function sekeco_icon( $name, $args = array() ) {
	$icons = sekeco_icons();

	if ( ! isset( $icons[ $name ] ) ) {
		return '';
	}

	$args  = wp_parse_args(
		$args,
		array(
			'class' => '',
			'size'  => 24,
			'label' => '',
		)
	);
	$size  = (int) $args['size'];
	$class = trim( 'sekeco-icon-svg ' . $args['class'] );
	$a11y  = '' === $args['label']
		? 'aria-hidden="true" focusable="false"'
		: 'role="img" aria-label="' . esc_attr( $args['label'] ) . '"';

	return sprintf(
		'<svg class="%1$s" width="%2$d" height="%2$d" viewBox="0 0 24 24" fill="none" %3$s>%4$s</svg>',
		esc_attr( $class ),
		$size,
		$a11y,
		$icons[ $name ] // Trusted: generated from the Solar icon set.
	);
}

/**
 * Expose the icon map to the editor before any block script runs.
 *
 * @return void
 */
function sekeco_enqueue_editor_icons() {
	wp_register_script( 'sekeco-icons', false, array(), SEKECO_VERSION, false );
	wp_enqueue_script( 'sekeco-icons' );
	wp_add_inline_script(
		'sekeco-icons',
		'window.sekecoIcons=' . wp_json_encode( sekeco_icons() ) . ';'
	);
}
add_action( 'enqueue_block_editor_assets', 'sekeco_enqueue_editor_icons', 1 );
